using System;namespace Recovered.Gameplay {public static class PtlRuntimeMessageBoxCodecCPU {static Func<SoundSetupImage,uint,uint[],uint> Route(Func<SoundSetupImage,uint,uint[],uint> leaf){Func<SoundSetupImage,uint,uint[],uint> route=null;route=delegate(SoundSetupImage m,uint address,uint[] args){if(address==0x6f01bc)return PtlThreadCodec.Decode(m,args[0],route);if(address==0x6f0145)return PtlThreadEncoder.Encode(m,args[0],route);if(address==0x6f00d9)return PtlRuntimeCapability.Supported(m,route);if(address==0x6f024e)return PtlThreadCodec.Getter(m,route);if(address==0x6ead5f)return PtlErrnoPointer.Get(m,route);if(address==0x6f0395)return PtlRuntimeThreadCPU.Acquire(m,leaf);return leaf(m,address,args);};return route;}public static uint Null(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlRuntimeMessageBox.EncodedNull(m,Route(leaf));}public static uint Message(SoundSetupImage m,uint text,uint caption,uint flags,uint frame,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlRuntimeMessageBox.Message(m,text,caption,flags,frame,Route(leaf));}}}
